package org.slavicmyths.marinka;
import java.util.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.monster.Monster;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;
import net.minecraft.world.damagesource.DamageSource;
/** Precision spear ally; finite counters, same UUID during curse, one retreat per attempt. */
public final class DobrynyaEntity extends WitchActor {
 private static final EntityDataAccessor<String> OWNER=SynchedEntityData.defineId(DobrynyaEntity.class,EntityDataSerializers.STRING);
 private static final EntityDataAccessor<Boolean> BULL=SynchedEntityData.defineId(DobrynyaEntity.class,EntityDataSerializers.BOOLEAN);
 public UUID owner,arena;public boolean retreated,incapacitated,parryUsed;public long curseUntil,lastHurt,recoverySince,resolveUntil;
 private Vec3 cover,charge;private final Set<UUID> swept=new HashSet<>();
 public DobrynyaEntity(EntityType<? extends DobrynyaEntity> t,Level w){super(t,w);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(OWNER,"");b.define(BULL,false);}
 public UUID syncedOwner(){try{return UUID.fromString(entityData.get(OWNER));}catch(Exception e){return null;}}
 public boolean bull(){return entityData.get(BULL);}private void bull(boolean value){if(bull()!=value){entityData.set(BULL,value);refreshDimensions();}}
 @Override public void onSyncedDataUpdated(EntityDataAccessor<?> key){super.onSyncedDataUpdated(key);if(key==BULL)refreshDimensions();}
 @Override protected EntityDimensions getDefaultDimensions(Pose p){return bull()?EntityDimensions.scalable(1.15F,1.7F):super.getDefaultDimensions(p);}
 public WitchYard.Entry yard(){return arena!=null&&level() instanceof ServerLevel w?WitchYard.get(w).yards.get(arena):null;}
 public MarinkaEntity boss(){var e=yard();return e!=null&&e.boss!=null&&level() instanceof ServerLevel w&&w.getEntity(e.boss) instanceof MarinkaEntity b&&b.active&&b.isAlive()?b:null;}
 public void bind(WitchYard.Entry e){bark(2);arena=e.id;retreated=false;incapacitated=false;parryUsed=false;cover=null;begin(WitchAction.FOLLOW);}
 public void endEncounter(){arena=null;setTarget(null);curseUntil=0;if(bull()||action()==WitchAction.TRANSFORM)begin(WitchAction.REVERT);else if(!recovering())begin(WitchAction.SALUTE);}
 public boolean recovering(){return action()==WitchAction.RETREAT||action()==WitchAction.DRINK||action()==WitchAction.RECOVER||action()==WitchAction.INCAPACITATED;}
 public void transform(int ticks){if(recovering()||bull()||action()==WitchAction.TRANSFORM)return;curseUntil=level().getGameTime()+ticks;begin(WitchAction.TRANSFORM);cue("aurochs_transform_01");bark(5);setTarget(null);}
 public void revert(){if(bull()||action()==WitchAction.TRANSFORM){curseUntil=0;begin(WitchAction.REVERT);cue("hero_return_01");bark(7);}}
 @Override public void tick(){super.tick();if(!(level() instanceof ServerLevel w)||!isAlive()||owner==null)return;entityData.set(OWNER,owner.toString());if(getPersistentData().getBoolean("HeroRecalling")||w.getGameTime()<getPersistentData().getLong("HeroArrivingUntil")){getNavigation().stop();setTarget(null);return;}var data=WitchYard.get(w.getServer().overworld());var canonical=data.heroes.get(owner);if(canonical!=null&&!canonical.equals(getUUID())){discard();return;}if(canonical==null){data.heroes.put(owner,getUUID());data.setDirty();}var p=w.getServer().getPlayerList().getPlayer(owner);var b=boss();if(arena==null&&p!=null&&p.level()==w&&(org.slavicmyths.bogatyr.BogatyrLedger.active(p)||org.slavicmyths.skim.SkimValley.get(w).lock(owner)!=null)){getNavigation().stop();setTarget(null);return;}if(arena!=null&&b==null)endEncounter();if(bull()&&w.getGameTime()>=curseUntil&&action()!=WitchAction.REVERT)revert();
  if(b!=null&&getHealth()<=34.5&&!retreated&&!bull()&&action()!=WitchAction.TRANSFORM&&!recovering()){retreated=true;bark(9);setTarget(null);var away=position().subtract(b.center()).multiply(1,0,1).normalize();if(away.lengthSqr()<.1)away=new Vec3(1,0,0);cover=org.slavicmyths.bogatyr.BogatyrLedger.safe(w,position().add(away.scale(12)),.8,2.2,3);if(cover==null)cover=org.slavicmyths.bogatyr.BogatyrLedger.safe(w,b.center().add(away.scale(20)),.8,2.2,3);begin(WitchAction.RETREAT);cue("grunt_hurt_01");if(p!=null)p.sendSystemMessage(net.minecraft.network.chat.Component.translatable("msg.slavicmyths.dobrynya_retreat"));}
  step(w,b);if(length()>0&&age()>=length())finish();if(length()>0||recovering())return;
  if(bull()){if(b!=null&&ready("bull")&&tickCount%4==0){face(b);charge=heading();cooldown("bull",160+random.nextInt(101));begin(WitchAction.BULL_CHARGE);cue("aurochs_charge_01");}return;}
  if(tickCount%4!=0)return;LivingEntity target=b!=null?b:w.getEntitiesOfClass(Monster.class,getBoundingBox().inflate(10),e->e.isAlive()&&!isAlliedTo(e)&&e.getTarget()==p).stream().min(Comparator.comparingDouble(this::distanceToSqr)).orElse(null);setTarget(target);
  if(b!=null&&b.action()==WitchAction.INTRO){if(p!=null&&distanceToSqr(p)>16)getNavigation().moveTo(p,1);return;}
  if(p!=null&&p.level()==w&&distanceToSqr(p)<36&&ready("ward")){for(var shot:w.getEntitiesOfClass(WitchBolt.class,getBoundingBox().inflate(12),s->!s.reflected&&s.reflectable&&s.activeBoss()!=null)){if(p.getBoundingBox().inflate(.5).clip(shot.position(),shot.position().add(shot.getDeltaMovement().scale(18))).isPresent()){face(shot.activeBoss());cooldown("ward",240);begin(WitchAction.WARD);cue("shield_ward_01");return;}}}
  if(target!=null){face(target);if(b!=null&&b.exposed()&&ready("unravel")&&edge(b)<=3.2){cooldown("unravel",340);begin(WitchAction.UNRAVEL);return;}if(ready("parry")&&edge(target)<3.8&&target.swinging&&random.nextFloat()<.6F){parryUsed=false;cooldown("parry",160);begin(WitchAction.PARRY);return;}
   if(ready("sidestep")&&b!=null&&b.action()==WitchAction.FIRE&&b.age()>4&&b.age()<12){Vec3 side=new Vec3(heading().z,0,-heading().x).scale(random.nextBoolean()?.9:-.9);if(w.noCollision(this,getBoundingBox().move(side))){move(MoverType.SELF,side);cooldown("sidestep",100);begin(WitchAction.SIDESTEP);return;}}
   if(ready("sweep")&&w.getEntitiesOfClass(Monster.class,getBoundingBox().inflate(3.25),m->m.isAlive()&&!isAlliedTo(m)).size()>=2){swept.clear();cooldown("sweep",280);begin(WitchAction.SWEEP);return;}
   boolean ownerActive=b==null||b.ownerActive(owner);if(ownerActive&&edge(target)<=2.6&&ready("combo")){cooldown("combo",120);begin(WitchAction.COMBO);return;}if(ownerActive&&edge(target)<=3.6&&ready("thrust")){cooldown("thrust",110);begin(WitchAction.THRUST);return;}if(tickCount%8==0)getNavigation().moveTo(target,1);
  }else if(p!=null&&p.level()==w&&distanceToSqr(p)>49){getNavigation().moveTo(p,1);if(arena==null&&distanceToSqr(p)>900&&getNavigation().isDone()){var at=org.slavicmyths.bogatyr.BogatyrLedger.safe(w,p.position(),.8,2.2,6);if(at!=null)teleportTo(at.x,at.y,at.z);}}
  if(getDeltaMovement().horizontalDistanceSqr()>.0004&&tickCount%12==0)cue("armor_step_01");if(tickCount%300==0&&ready("ambient")){cooldown("ambient",240+random.nextInt(141));cue("breath_idle_01");}
 }
 private void strike(float damage,double reach,double angle){var target=getTarget();if(target!=null&&target.isAlive()&&cone(target,reach,angle)&&hasLineOfSight(target)){target.invulnerableTime=0;target.hurt(damageSources().mobAttack(this),damage);if(action()==WitchAction.THRUST)target.knockback(target instanceof MarinkaEntity?.08:.45,getX()-target.getX(),getZ()-target.getZ());cue("spear_impact_01");}}
 private void step(ServerLevel w,MarinkaEntity b){int t=age();switch(action()){
 case COMBO->{if((t==10||t==20)&&getTarget()!=null){face(getTarget());Vec3 advance=getTarget().position().subtract(position()).multiply(1,0,1).normalize().scale(.6);if(edge(getTarget())>2.1&&w.noCollision(this,getBoundingBox().move(advance)))move(MoverType.SELF,advance);}if(t==6)strike(9,2.6,95);if(t==13)strike(10,2.6,95);if(t==23)strike(15,2.6,95);if(t==3||t==10||t==20)cue("spear_swing_01");}
 case THRUST->{if(t==4)cue("spear_swing_01");if(t==8)strike(21,3.6,55);}
 case PARRY->{if(t==10&&parryUsed){strike(13,3.6,95);if(getTarget() instanceof MarinkaEntity m)m.begin(WitchAction.EXHAUSTED,7);else if(getTarget() instanceof net.minecraft.world.entity.Mob mob){mob.getNavigation().stop();mob.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN,12,5));}}}
 case SWEEP->{if(t==4)cue("spear_sweep_01");if(t==9||t==15){int count=0;for(var e:w.getEntitiesOfClass(LivingEntity.class,getBoundingBox().inflate(3.25),e->e instanceof Monster||e instanceof MarinkaEntity||e instanceof TurMinion)){if(count>=5)break;if(!isAlliedTo(e)&&cone(e,3.25,210)&&hasLineOfSight(e)&&swept.add(e.getUUID())){e.hurt(damageSources().mobAttack(this),15);if(!(e instanceof MarinkaEntity))e.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN,22));count++;}}}}
 case WARD->{if(t>=6&&t<=13&&ready("reflected")){for(var shot:w.getEntitiesOfClass(WitchBolt.class,getBoundingBox().inflate(2.2),s->s.reflectable&&!s.reflected)){var toward=shot.position().subtract(position()).multiply(1,0,1).normalize();if(toward.dot(heading())>=Math.cos(Math.toRadians(55))&&shot.reflect(this)){cooldown("reflected",24);cue("magic_deflect_01");bark(4);break;}}}}
 case UNRAVEL->{if(t==13&&b!=null&&b.exposed()&&edge(b)<=3.2&&hasLineOfSight(b)){b.breakWard();cue("unravel_hex_01");}}
 case TRANSFORM->{if(t==29)bull(true);}
 case REVERT->{if(t==15)bull(false);}
 case BULL_CHARGE->{if(t>=9&&t<=20&&charge!=null){if(b!=null&&yard()!=null&&yard().radius(position().add(charge.scale(.5)))<=23&&w.noCollision(this,getBoundingBox().move(charge.scale(.5))))move(MoverType.SELF,charge.scale(.5));if(t==14&&b!=null&&edge(b)<=3&&hasLineOfSight(b))b.hurt(damageSources().mobAttack(this),12);}}
 case RETREAT->{if(t>=12&&cover!=null)getNavigation().moveTo(cover.x,cover.y,cover.z,1.2);}
 case DRINK->{if(cover!=null&&distanceToSqr(cover)>2&&t<30)getNavigation().moveTo(cover.x,cover.y,cover.z,1.2);if(t==18)cue("elixir_drink_01");if((t==44||t==60)&&w.getGameTime()-lastHurt>=20){heal(Math.min(36,Math.max(0,106-getHealth())));}}
 case RECOVER->{if(w.getGameTime()-Math.max(recoverySince,lastHurt)>=160){begin(WitchAction.RALLY);cue("hero_return_01");bark(7);}}
 default->{}
 }}
 private void finish(){switch(action()){case TRANSFORM->begin(WitchAction.AUROCHS);case REVERT->{bull(false);begin(WitchAction.IDLE);}case RETREAT->{begin(WitchAction.DRINK);recoverySince=level().getGameTime();}case DRINK->begin(WitchAction.RECOVER,0);default->begin(bull()?WitchAction.AUROCHS:WitchAction.IDLE);}}
 public float mitigation(DamageSource s){if(s.is(net.minecraft.tags.DamageTypeTags.BYPASSES_INVULNERABILITY))return 1;boolean magic=s.getMsgId().startsWith("marinka_")||s.is(net.minecraft.world.damagesource.DamageTypes.MAGIC)||s.is(net.minecraft.world.damagesource.DamageTypes.INDIRECT_MAGIC);var at=s.getSourcePosition();boolean front=at!=null&&at.subtract(position()).multiply(1,0,1).normalize().dot(heading())>=Math.cos(Math.toRadians(55));if(!bull()&&!magic&&action()==WitchAction.PARRY&&age()>=4&&age()<=8&&!parryUsed&&front){parryUsed=true;cue("spear_parry_01");bark(3);return .75F*.3F;}if(!bull()&&magic&&action()==WitchAction.WARD&&age()>=1&&age()<=16&&front)return .6F;return magic?1:.75F;}
 @Override public boolean addEffect(net.minecraft.world.effect.MobEffectInstance effect,Entity source){var type=effect.getEffect();if(type==net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN||type==net.minecraft.world.effect.MobEffects.WEAKNESS||type==net.minecraft.world.effect.MobEffects.CONFUSION){String key="resolve_"+effect.getDescriptionId();if(!ready(key))return false;cooldown(key,240);effect=new net.minecraft.world.effect.MobEffectInstance(type,Math.max(1,Math.round(effect.getDuration()*.65F)),effect.getAmplifier(),effect.isAmbient(),effect.isVisible(),effect.showIcon());}return super.addEffect(effect,source);}
 @Override public boolean isAlliedTo(Entity e){return e.getUUID().equals(owner)||e instanceof DobrynyaEntity||e instanceof org.slavicmyths.bogatyr.IlyaEntity||super.isAlliedTo(e);}
 @Override public boolean hurt(DamageSource s,float amount){if(s.getEntity()!=null&&isAlliedTo(s.getEntity()))return false;boolean result=super.hurt(s,amount);if(result){lastHurt=level().getGameTime();if(ready("hurt")){cooldown("hurt",28);cue("grunt_hurt_01");}}return result;}
 @Override public void die(DamageSource s){if(arena!=null){incapacitated=true;begin(WitchAction.INCAPACITATED);}super.die(s);if(owner!=null&&level() instanceof ServerLevel w){var d=WitchYard.get(w.getServer().overworld());d.heroes.remove(owner,getUUID());d.setDirty();}}
 @Override protected void dropAllDeathLoot(ServerLevel w,DamageSource s){}@Override protected void dropExperience(Entity cause){}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(owner!=null)n.putUUID("Owner",owner);if(arena!=null)n.putUUID("Arena",arena);n.putBoolean("Retreated",retreated);n.putBoolean("Incapacitated",incapacitated);n.putLong("LastHurt",lastHurt);n.putLong("RecoverySince",recoverySince);n.putLong("ResolveUntil",resolveUntil);if(cover!=null){n.putDouble("CoverX",cover.x);n.putDouble("CoverY",cover.y);n.putDouble("CoverZ",cover.z);}}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);owner=n.hasUUID("Owner")?n.getUUID("Owner"):null;arena=n.hasUUID("Arena")?n.getUUID("Arena"):null;retreated=n.getBoolean("Retreated");incapacitated=n.getBoolean("Incapacitated");lastHurt=n.getLong("LastHurt");recoverySince=n.getLong("RecoverySince");resolveUntil=n.getLong("ResolveUntil");if(n.contains("CoverX"))cover=new Vec3(n.getDouble("CoverX"),n.getDouble("CoverY"),n.getDouble("CoverZ"));bull(false);curseUntil=0;try{var a=WitchAction.valueOf(n.getString("WitchAction"));if(a==WitchAction.RETREAT||a==WitchAction.DRINK||a==WitchAction.RECOVER||a==WitchAction.INCAPACITATED)resume(n,a);}catch(Exception ignored){}}
}
